package com.eventhub.service; import com.eventhub.dto.AnalyticsSummaryResponse; import com.eventhub.entity.*; import com.eventhub.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; @Service @RequiredArgsConstructor public class AnalyticsService {private final EventRepository events;private final RegistrationRepository registrations;private final AttendanceRepository attendance;private final WaitlistRepository waitlists; @Transactional(readOnly=true) public AnalyticsSummaryResponse summary(){long total=events.count(),upcoming=events.countByEventDateGreaterThanEqualAndStatusNot(LocalDate.now(),EventStatus.CANCELLED),completed=events.countByStatus(EventStatus.COMPLETED),regs=registrations.count(),att=attendance.count(),wait=waitlists.countByStatus(WaitlistStatus.WAITING),cancel=registrations.countByStatus(RegistrationStatus.CANCELLED);return new AnalyticsSummaryResponse(total,upcoming,completed,regs,att,wait,cancel);}}
